/* Community service worker (generated by vite-plugins/build-version.ts).
 *
 * - Caches hashed JS/CSS on demand; /assets/* is served cache-first.
 *   Installation never downloads unused routes or locales, which would
 *   compete with the current page on slow connections.
 * - Caches of the previous build are kept so a tab opened before a deploy
 *   can still load its lazy chunks.
 * - Frontend page navigations are network-first with the last shell as an
 *   offline fallback. API, streaming, media, OAuth and federation requests
 *   are never intercepted. Emoji images under /emoji-assets/ stay on the
 *   browser HTTP cache (stable UUID URLs, immutable for a year).
 * - A page message { type: 'emoji-revalidate', revision } conditionally
 *   fetches /api/v1/custom_emojis and replies on the transferred port.
 *   The catalogue itself is stored by the page, not in this cache.
 */
const BUILD = __BUILD_ID__
const ASSET_PREFIX = 'community-assets-'
const ASSET_CACHE = ASSET_PREFIX + BUILD
const SHELL_CACHE = 'community-shell'
const SHELL_KEY = '/__community_shell__'
const KEEP_BUILDS = 2

// Server namespaces whose navigations must reach the network untouched
// (keep in sync with nonSPAPrefixes in cmd/community/spa.go).
const BYPASS = [
  '/api/', '/oauth/', '/miauth/', '/auth/', '/.well-known/', '/nodeinfo', '/users/', '/ap/', '/actor',
  '/inbox', '/outbox', '/_matrix/', '/_synapse/', '/media/', '/emoji-assets/', '/card-images/',
  '/system/', '/proxy/', '/health', '/live', '/ready', '/metrics', '/admin/logs/', '/setup',
  '/version.json', '/sw.js', '/manifest', '/favicon.ico',
]

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    await caches.open(ASSET_CACHE)
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), 5000)
    try {
      const shell = await fetch('/', { cache: 'no-store', credentials: 'same-origin', signal: controller.signal })
      if (shell.ok) await (await caches.open(SHELL_CACHE)).put(SHELL_KEY, shell)
    } catch { /* offline install: keep the previous shell */ }
    finally { clearTimeout(timer) }
    await self.skipWaiting()
  })())
})

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const assetCaches = (await caches.keys()).filter((k) => k.startsWith(ASSET_PREFIX) && k !== ASSET_CACHE)
    // caches.keys() is in creation order: keep the newest previous builds.
    const stale = assetCaches.slice(0, Math.max(0, assetCaches.length - (KEEP_BUILDS - 1)))
    await Promise.all(stale.map((k) => caches.delete(k)))
    await self.clients.claim()
  })())
})

self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') {
    void self.skipWaiting()
    return
  }
  if (!event.data || event.data.type !== 'emoji-revalidate' || !event.ports || !event.ports[0]) return
  event.waitUntil(revalidateCustomEmoji(event.ports[0], event.data.revision))
})

// Ack before the fetch so a page still running an older worker can fall
// through quickly. 304 returns no catalogue body.
async function revalidateCustomEmoji(port, revision) {
  port.postMessage({ accepted: true })
  const headers = { Accept: 'application/json' }
  if (typeof revision === 'string' && revision) headers['If-None-Match'] = revision
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 20000)
  try {
    const res = await fetch('/api/v1/custom_emojis', {
      method: 'GET', headers, credentials: 'same-origin', cache: 'no-store', signal: controller.signal,
    })
    if (res.status === 304) {
      port.postMessage({ status: 304, etag: res.headers.get('ETag'), body: null })
      return
    }
    const body = res.ok ? await res.json() : null
    port.postMessage({ status: res.status, etag: res.headers.get('ETag'), body })
  } catch {
    port.postMessage({ error: true })
  } finally {
    clearTimeout(timer)
  }
}

// Hashed /assets files are named by content; any query (none is added by
// the build) is ignored so cached copies always match.
async function serveAsset(request, event) {
  const url = new URL(request.url)
  url.search = ''
  const cached = await caches.match(url.href)
  if (cached) return cached
  const res = await fetch(request)
  if (res.ok) {
    const copy = res.clone()
    event.waitUntil(caches.open(ASSET_CACHE).then((cache) => cache.put(url.href, copy)).catch(() => {}))
  }
  return res
}

async function serveNavigation(request, event) {
  const network = (async () => {
    const res = await fetch(request)
    const type = res.headers.get('Content-Type') || ''
    if (res.status === 200 && type.startsWith('text/html')) {
      const copy = res.clone()
      event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.put(SHELL_KEY, copy)).catch(() => {}))
    }
    return res
  })()
  // Keep refreshing the shell after a cached fallback has rendered. API
  // data is always fetched normally and never stored in this cache.
  event.waitUntil(network.catch(() => {}))
  let timer
  const slow = new Promise((resolve) => { timer = setTimeout(() => resolve(null), 3000) })
  try {
    const res = await Promise.race([network, slow])
    if (res) return res
    const shell = await caches.match(SHELL_KEY)
    return shell || await network
  } catch (err) {
    const shell = await caches.match(SHELL_KEY)
    if (shell) return shell
    throw err
  } finally { clearTimeout(timer) }
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin) return
  if (url.pathname.startsWith('/assets/')) {
    event.respondWith(serveAsset(request, event))
    return
  }
  if (request.mode === 'navigate' && !BYPASS.some((p) => url.pathname.startsWith(p))) {
    event.respondWith(serveNavigation(request, event))
  }
})
